scriptTask.script:
var msg = execution.getVariable('_user_message') || '';
var safeMsg = msg.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\r/g, '\\r');
var creditScore = execution.getVariable('credit_score');
var decision = execution.getVariable('decision');
var cugaKey = execution.getVariable('cugaProcessKey');
var body = '{"jsonrpc":"2.0","method":"tools/call","params":{"name":"execute_task","arguments":{"task_id":"Activity_0oydey5","ctx":{"process_instance_id":"' + execution.processInstanceId + '","element_id":"Activity_0oydey5","element_name":"check credit","current_state":{"process_variables":{"credit_score":' + creditScore + ',"decision":"' + decision + '","cugaProcessKey":"' + cugaKey + '","user_message":"' + safeMsg + '"}},"execution_history":[],"process_model_summary":{}}}},"id":1}';
var url = new java.net.URL('http://host.docker.internal:8090/mcp');
var conn = url.openConnection();
conn.setRequestMethod('POST');
conn.setRequestProperty('Content-Type', 'application/json');
conn.setRequestProperty('Accept', 'application/json, text/event-stream');
conn.setReadTimeout(120000);
conn.setDoOutput(true);
var os = conn.getOutputStream();
os.write(new java.lang.String(body).getBytes('UTF-8'));
os.close();
var br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), 'UTF-8'));
var raw = '';
var line;
while ((line = br.readLine()) !== null) {
    if (line.indexOf('data:') === 0) { raw = line.substring(5).trim(); break; }
}
br.close();
var resp = JSON.parse(raw);
if (!resp.result) throw new Error('execute_task error: ' + JSON.stringify(resp.error || resp));
var vars = JSON.parse(resp.result.content[0].text).process_variables;
if (vars && vars.credit_score !== undefined) {
    execution.setVariable('credit_score', Number(vars.credit_score));
}

var msg = execution.getVariable('_user_message') || '';
var safeMsg = msg.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\r/g, '\\r');
var creditScore = execution.getVariable('credit_score');
var decision = execution.getVariable('decision');
var cugaKey = execution.getVariable('cugaProcessKey');
var body = '{"jsonrpc":"2.0","method":"tools/call","params":{"name":"route_gateway","arguments":{"gateway_id":"Gateway_09ad5fc","ctx":{"process_instance_id":"' + execution.processInstanceId + '","element_id":"Gateway_09ad5fc","element_name":"credit decision","current_state":{"process_variables":{"credit_score":' + creditScore + ',"decision":"' + decision + '","cugaProcessKey":"' + cugaKey + '","user_message":"' + safeMsg + '"}},"execution_history":[],"process_model_summary":{},"available_flows":[{"id":"Flow_0ybszcv","source_ref":"Gateway_09ad5fc","target_ref":"Task_HookHttp","name":"yes","condition":null},{"id":"Flow_1jgea85","source_ref":"Gateway_09ad5fc","target_ref":"Activity_131ar38","name":"no","condition":null}]}}},"id":1}';
var url = new java.net.URL('http://host.docker.internal:8090/mcp');
var conn = url.openConnection();
conn.setRequestMethod('POST');
conn.setRequestProperty('Content-Type', 'application/json');
conn.setRequestProperty('Accept', 'application/json, text/event-stream');
conn.setReadTimeout(120000);
conn.setDoOutput(true);
var os = conn.getOutputStream();
os.write(new java.lang.String(body).getBytes('UTF-8'));
os.close();
var br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), 'UTF-8'));
var raw = '';
var line;
while ((line = br.readLine()) !== null) {
    if (line.indexOf('data:') === 0) { raw = line.substring(5).trim(); break; }
}
br.close();
var resp = JSON.parse(raw);
if (!resp.result) throw new Error('route_gateway error: ' + JSON.stringify(resp.error || resp));
var flowId = resp.result.content[0].text.trim().replace(/^"|"$/g, '');
execution.setVariable('gatewayDecision', flowId);

var creditScore = execution.getVariable('credit_score');
var decision = execution.getVariable('decision');
var cugaKey = execution.getVariable('cugaProcessKey');
var body = '{"jsonrpc":"2.0","method":"tools/call","params":{"name":"evaluate_hook","arguments":{"hook_id":"Flow_0ybszcv","ctx":{"process_instance_id":"' + execution.processInstanceId + '","element_id":"Task_HookHttp","element_name":"Notify CUGA FLO Hook","current_state":{"process_variables":{"credit_score":' + creditScore + ',"decision":"' + decision + '","cugaProcessKey":"' + cugaKey + '"}},"execution_history":[],"process_model_summary":{}}}},"id":1}';
var url = new java.net.URL('http://host.docker.internal:8090/mcp');
var conn = url.openConnection();
conn.setRequestMethod('POST');
conn.setRequestProperty('Content-Type', 'application/json');
conn.setRequestProperty('Accept', 'application/json, text/event-stream');
conn.setReadTimeout(120000);
conn.setDoOutput(true);
var os = conn.getOutputStream();
os.write(new java.lang.String(body).getBytes('UTF-8'));
os.close();
var br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), 'UTF-8'));
var raw = '';
var line;
while ((line = br.readLine()) !== null) {
    if (line.indexOf('data:') === 0) { raw = line.substring(5).trim(); break; }
}
br.close();
var resp = JSON.parse(raw);
if (!resp.result) throw new Error('evaluate_hook error: ' + JSON.stringify(resp.error || resp));
